    genesisTagline: 'Your money, finally clear.',
    genesisPrivacyTitle: 'Nothing leaves here.',
    genesisPrivacyText: 'Your data tries to leave and comes back in. No server, no account: it stays on your phone. Four questions and you\'re in.',
    genesisStart: 'Start — takes 20 seconds',
    genesisProgress1: 'Question 1 of 4', genesisProgress2: 'Question 2 of 4', genesisProgress3: 'Question 3 of 4', genesisProgress4Last: 'Question 4 of 4 — last one',
    genesisQ1Title: 'If your income stopped today.',
    genesisQ1Sub: 'How long could you go, spending like now?',
    genesisQ1Opt1: 'Less than a month', genesisQ1Opt2: 'Two or three months', genesisQ1Opt3: 'About half a year', genesisQ1Opt4: 'A year or more', genesisQ1Opt5: 'I don\'t know',
    genesisQ2Title: 'The market drops 20%.',
    genesisQ2Sub: 'What would you do?',
