    genesisQ4Title: 'How does your income arrive?',
    genesisQ4Sub: 'Fixed salary or more unpredictable — changes how much of a buffer you actually need.',
    genesisQ4Opt1: 'Always the same, every month', genesisQ4Opt2: 'Varies a bit, but predictable', genesisQ4Opt3: 'Changes a lot, month to month', genesisQ4Opt4: 'Prefer not to say',
    dashOggiPuoiSpendere: 'You can spend today',
    dashComeStaiMesso: 'How your week is looking',
    dashToccaSegnaSpesa: 'Tap to log an expense',
    dashAriaOggiPuoiSpendere: (money) => `You can spend ${money} today. Tap to log an expense.`,
    dashSpesoFinora: 'Spent so far this month',
    dashEntrateMenoUscite: 'Income minus expenses, this month',
    dashImportTitle: 'See your real money.',
    dashImportSub: 'Not the example: import your statement — CSV, PDF, or even a screenshot.',
    dashImportBtn: 'Import your transactions',
    dashImportBackup: 'Already used Momentum from a browser? Import your backup here',
    wnEyebrow: 'Momentum · News',
    wnTitle: 'What\'s new',
    wnClose: 'Got it',
    wn0720_0_t: 'One consistent style, everywhere',
    wn0720_0_d: 'Consistent icons instead of scattered emoji, and technical terms translated into plain language (e.g. "Decisive" instead of "Apex Predator") — the same Momentum, easier to read at a glance.',
    wn0720_1_t: 'Real e-invoicing, not just a PDF',
    wn0720_1_d: 'If you have an Italian VAT number, you can now generate the official FatturaPA XML right on your phone, with a guide that tells you what\'s missing before you upload it.',
    wn0720_2_t: 'Get paid with a QR code',
    wn0720_2_d: 'A SEPA transfer QR code ready to scan with your banking app — no more copying IBANs by hand.',
    wn0721_0_t: 'Split expenses, no account needed',
    wn0721_0_d: 'Dinner, a trip, rent: create a group and instantly know who owes what to whom — everything stays on your phone, no server involved.',
    wn0721_1_t: 'Create an invoice in a few taps',
    wn0721_1_d: 'Client, amount, reason: Momentum calculates net and withholding tax on the fly and generates a ready-to-send document.',
    wn0810_0_t: 'The home screen, redesigned',
    wn0810_0_d: 'The number that actually matters — how much you can spend today — is now the first thing you see, front and center, instead of buried below the fold.',
    wn0810_1_t: 'Numbers that are easier to read',
    wn0810_1_d: 'One consistent style for every kind of text across the app — at a glance you can tell what\'s a real number and what\'s just an explanation.',
    wn0817_0_t: 'Notifications, one at a time',
    wn0817_0_d: 'Tax deadlines, regulation changes, price alerts: each one can now be turned off on its own — no more disabling all of them just to silence one.',
    wn0817_1_t: 'Understands meaning, not just words',
    wn0817_1_d: 'A local language-understanding model (optional, downloadable in Momentum Vault) now recognizes a question even when you phrase it differently from how you first taught it.',
    wn0826_0_t: 'Four questions, tailored to you',
    wn0826_0_d: 'First launch now also asks how long you could hold on if your income stopped — and immediately shows you what changed for you, with your real numbers.',
    wn0826_1_t: '"I don\'t invest" is now a real answer',
    wn0826_1_d: 'If you choose not to invest, the app stops suggesting how to — it respects your choice instead of pushing back.',
    wn0827_0_t: 'Partita IVA Spain, with your real invoices',
    wn0827_0_d: 'Not just a simulator anymore: if you work as an autónomo, RETA and IRPF are now calculated from the real transactions you record, month by month.',
    wn0827_1_t: 'More reliable expense splitting',
    wn0827_1_d: 'Who owes what to whom is now always correct even for people who join a group later (not just whoever created it), and two people with the same name no longer get mixed up.',
    wn0827_2_t: 'Sync between devices, fixed at the root',
    wn0827_2_d: 'Renaming a group, adding an expense, or writing in chat now really reaches your other connected devices, right away.',
    wn0827_3_t: 'How much is really down to you, month by month',
    wn0827_3_d: 'In a stock\'s analysis, a chart now shows how much of its performance is really "yours" and not just the market going up — month by month, not just a single number.',
    wn0828_0_t: 'Your import channels, watching themselves',
    wn0828_0_d: 'Screenshots, CSV, and PDF that prove reliable start saving themselves automatically, without asking for confirmation every time — visible in Momentum Vault, under imports.',
    wn0828_1_t: 'The backup prompt before installing it as an app',
    wn0828_1_d: 'On iPhone, adding Momentum to your Home Screen now warns you to save a backup first — and anyone who already used it from a browser can recover their data in one tap.',
    wn0828_2_t: 'No more duplicates between notification and statement',
    wn0828_2_d: 'An expense first seen from a notification or screenshot, and later confirmed by the bank statement that arrives afterward, no longer shows up twice.',
    wn0828_3_t: 'The app tells you when it learned something',
    wn0828_3_d: 'Correcting an expense\'s category now immediately shows that Momentum will remember it — no longer an invisible change.',
    wn0830_0_t: 'Just ask "Apple" or "Tesla"',
    wn0830_0_d: 'Typing a bare stock or crypto name in chat now works — it used to need a full phrase ("what\'s ... worth"), and if it really finds nothing it says so clearly, instead of the usual "I don\'t know".',
    wn0830_1_t: 'Real stock price history, zero setup',
    wn0830_1_d: 'Apple, Tesla, NVIDIA and many others now show a real historical chart even without a personal data key — always honestly disclosed when the price comes from this source.',
    wn0830_2_t: 'Comps and crypto positioning, now in chat too',
    wn0830_2_d: 'Peer comparison (EV/EBITDA) and crypto derivatives positioning (funding rate, crowding) used to be button-only — now you can also just ask, e.g. "am I too crowded on bitcoin?".',
    wn0830_3_t: 'No more endless waiting',
    wn0830_3_d: 'If an external source doesn\'t respond, Momentum now says so within seconds instead of staying stuck on "searching..." forever.',
