    dashImportBtn: 'Importiere deine Umsätze',
    dashImportBackup: 'Momentum schon im Browser genutzt? Importiere hier dein Backup',
    wnEyebrow: 'Momentum · Neuigkeiten',
    wnTitle: 'Was ist neu',
    wnClose: 'Verstanden',
    wn0720_0_t: 'Ein einziger Stil, überall',
    wn0720_0_d: 'Einheitliche Icons statt verstreuter Emojis, und Fachbegriffe klar übersetzt (z. B. "Entschlossen" statt "Apex Predator") — dasselbe Momentum, nur leichter auf einen Blick zu lesen.',
    wn0720_1_t: 'Echte elektronische Rechnung, nicht nur ein PDF',
    wn0720_1_d: 'Wer eine italienische USt-IdNr. hat, kann jetzt das offizielle FatturaPA-XML direkt auf dem Handy erstellen, mit einer Anleitung, die zeigt, was vor dem Hochladen noch fehlt.',
    wn0720_2_t: 'Lass dich mit einem QR-Code bezahlen',
    wn0720_2_d: 'Ein SEPA-Überweisungs-QR-Code, bereit zum Scannen mit der Banking-App — kein IBAN mehr von Hand abtippen.',
    wn0721_0_t: 'Ausgaben teilen, ohne Konto',
    wn0721_0_d: 'Abendessen, Reise, Miete: Erstelle eine Gruppe und weißt sofort, wer wem was schuldet — alles bleibt auf deinem Handy, kein Server dazwischen.',
    wn0721_1_t: 'Rechnung in wenigen Schritten erstellen',
    wn0721_1_d: 'Kunde, Betrag, Grund: Momentum berechnet Netto und Quellensteuer sofort und erstellt ein versandfertiges Dokument.',
    wn0810_0_t: 'Der Startbildschirm, neu gestaltet',
    wn0810_0_d: 'Die Zahl, die wirklich zählt — wie viel du heute ausgeben kannst — ist jetzt das Erste, was du siehst, mittig und groß, statt weiter unten versteckt.',
    wn0810_1_t: 'Zahlen, die leichter zu lesen sind',
    wn0810_1_d: 'Ein einheitlicher Stil für jede Art von Text in der ganzen App — auf einen Blick erkennst du, was eine echte Zahl und was nur eine Erklärung ist.',
    wn0817_0_t: 'Benachrichtigungen, einzeln',
    wn0817_0_d: 'Steuerfristen, Gesetzesänderungen, Preisalarme: Jede lässt sich jetzt einzeln abschalten — du musst nicht mehr alle deaktivieren, um nur eine loszuwerden.',
    wn0817_1_t: 'Versteht die Bedeutung, nicht nur die Worte',
    wn0817_1_d: 'Ein lokales Sprachverständnis-Modell (optional, herunterladbar in Momentum Vault) erkennt eine Frage jetzt auch, wenn du sie anders formulierst als beim ersten Mal.',
    wn0826_0_t: 'Vier Fragen, auf dich zugeschnitten',
    wn0826_0_d: 'Der erste Start fragt jetzt auch, wie lange du durchhalten könntest, wenn dein Einkommen stoppen würde — und zeigt dir sofort, was sich für dich geändert hat, mit deinen echten Zahlen.',
    wn0826_1_t: '"Ich investiere nicht" ist jetzt eine echte Antwort',
    wn0826_1_d: 'Wer sich gegen Investieren entscheidet, bekommt keine Vorschläge mehr dazu — die App respektiert die Wahl, statt nachzuhaken.',
    wn0827_0_t: 'Partita IVA Spanien, mit deinen echten Rechnungen',
    wn0827_0_d: 'Nicht mehr nur ein Simulator: Wenn du als Autónomo arbeitest, werden RETA und IRPF jetzt aus den echten Transaktionen berechnet, die du Monat für Monat erfasst.',
    wn0827_1_t: 'Zuverlässigere Kostenteilung',
    wn0827_1_d: 'Wer wem was schuldet, ist jetzt immer korrekt, auch für alle, die später einer Gruppe beitreten (nicht nur für die Ersteller), und zwei Personen mit demselben Namen werden nicht mehr verwechselt.',
    wn0827_2_t: 'Synchronisierung zwischen Geräten, an der Wurzel behoben',
    wn0827_2_d: 'Eine Gruppe umbenennen, eine Ausgabe hinzufügen oder im Chat schreiben erreicht jetzt wirklich deine anderen verbundenen Geräte, sofort.',
    wn0827_3_t: 'Wie viel wirklich dein Verdienst ist, Monat für Monat',
    wn0827_3_d: 'In der Analyse einer Aktie zeigt ein Diagramm jetzt, wie viel ihrer Entwicklung wirklich „ihr eigenes" ist und nicht nur der steigende Markt — Monat für Monat, nicht nur eine einzelne Zahl.',
    wn0828_0_t: 'Deine Import-Kanäle, die sich selbst überwachen',
    wn0828_0_d: 'Screenshots, CSV und PDF, die sich als zuverlässig erweisen, speichern sich jetzt von selbst, ohne jedes Mal eine Bestätigung zu verlangen — sichtbar in Momentum Vault, unter Importe.',
    wn0828_1_t: 'Der Backup-Hinweis vor der Installation als App',
    wn0828_1_d: 'Auf dem iPhone warnt das Hinzufügen von Momentum zum Home-Bildschirm jetzt, vorher ein Backup zu speichern — und wer es schon im Browser genutzt hat, kann seine Daten mit einem Tipp wiederherstellen.',
    wn0828_2_t: 'Keine Doppelten mehr zwischen Benachrichtigung und Kontoauszug',
    wn0828_2_d: 'Eine Ausgabe, die zuerst über eine Benachrichtigung oder einen Screenshot gesehen und später durch den später eintreffenden Kontoauszug bestätigt wurde, erscheint nicht mehr doppelt.',
    wn0828_3_t: 'Die App sagt dir, wenn sie etwas gelernt hat',
    wn0828_3_d: 'Die Kategorie einer Ausgabe zu korrigieren zeigt jetzt sofort, dass Momentum es sich merkt — kein unsichtbarer Wechsel mehr.',
    wn0830_0_t: 'Frag einfach "Apple" oder "Tesla"',
    wn0830_0_d: 'Einen nackten Aktien- oder Krypto-Namen im Chat einzugeben funktioniert jetzt — vorher brauchte es einen ganzen Satz ("wie viel ist ... wert"), und wenn wirklich nichts gefunden wird, sagt es das jetzt klar, statt dem üblichen "weiß ich noch nicht".',
    wn0830_1_t: 'Aktienkurs-Historie, ganz ohne Einrichtung',
    wn0830_1_d: 'Apple, Tesla, NVIDIA und viele andere zeigen jetzt ein echtes Kursdiagramm auch ohne eigenen Datenschlüssel — immer ehrlich angegeben, wenn der Preis aus dieser Quelle stammt.',
    wn0830_2_t: 'Vergleichsunternehmen und Krypto-Positionierung, jetzt auch im Chat',
    wn0830_2_d: 'Der Vergleich mit Branchenkollegen (EV/EBITDA) und die Positionierung bei Krypto-Derivaten (Funding Rate, Überfüllung) gab es bisher nur als Button — jetzt auch per Frage, z. B. "bin ich bei Bitcoin zu überfüllt?".',
    wn0830_3_t: 'Kein endloses Warten mehr',
    wn0830_3_d: 'Antwortet eine externe Quelle nicht, sagt Momentum das jetzt innerhalb weniger Sekunden, statt für immer auf "ich suche..." hängen zu bleiben.',
