    wn0720_0_t: 'Un seul style, partout',
    wn0720_0_d: 'Des icônes cohérentes à la place des emojis épars, et les termes techniques traduits clairement (ex. « Décidé » au lieu de « Apex Predator ») — le même Momentum, plus facile à lire d\'un coup d\'œil.',
    wn0720_1_t: 'Vraie facture électronique, pas juste un PDF',
    wn0720_1_d: 'Si tu as une Partita IVA, tu peux maintenant générer le XML officiel FatturaPA directement sur ton téléphone, avec un guide qui indique ce qui manque avant de le charger.',
    wn0720_2_t: 'Fais-toi payer avec un QR code',
    wn0720_2_d: 'Un QR code de virement SEPA prêt à scanner avec l\'appli de ta banque — plus besoin de recopier un IBAN à la main.',
    wn0721_0_t: 'Partage les dépenses, sans compte',
    wn0721_0_d: 'Dîner, voyage, loyer : crée un groupe et sache tout de suite qui doit quoi à qui — tout reste sur ton téléphone, aucun serveur dans l\'histoire.',
    wn0721_1_t: 'Crée une facture en quelques gestes',
    wn0721_1_d: 'Client, montant, motif : Momentum calcule le net et la retenue à la source instantanément et génère le document prêt à envoyer.',
    wn0810_0_t: 'L\'écran d\'accueil, repensé',
    wn0810_0_d: 'Le chiffre qui compte vraiment — combien tu peux dépenser aujourd\'hui — est maintenant la première chose que tu vois, au centre, plutôt que caché plus bas.',
    wn0810_1_t: 'Des chiffres plus faciles à lire',
    wn0810_1_d: 'Un style unique pour chaque type de texte dans toute l\'appli — d\'un coup d\'œil tu distingues ce qui est une vraie donnée et ce qui n\'est qu\'une explication.',
    wn0817_0_t: 'Notifications, une par une',
    wn0817_0_d: 'Échéances fiscales, changements de réglementation, alertes de prix : chacune peut maintenant être désactivée seule — plus besoin de tout couper pour en faire taire une seule.',
    wn0817_1_t: 'Comprend le sens, pas seulement les mots',
    wn0817_1_d: 'Un modèle de compréhension du langage local (optionnel, téléchargeable dans Momentum Vault) reconnaît maintenant une question même formulée différemment de la première fois.',
    wn0826_0_t: 'Quatre questions, sur mesure pour toi',
    wn0826_0_d: 'Le premier lancement demande maintenant aussi combien de temps tu pourrais tenir si tes revenus s\'arrêtaient — et te montre aussitôt ce qui a changé pour toi, avec tes vrais chiffres.',
    wn0826_1_t: '« Je n\'investis pas » est maintenant une vraie réponse',
    wn0826_1_d: 'Qui choisit de ne pas investir ne reçoit plus de suggestions pour le faire — l\'appli respecte le choix au lieu d\'insister.',
    wn0827_0_t: 'Partita IVA Espagne, avec tes vraies factures',
    wn0827_0_d: 'Plus seulement un simulateur : si tu travailles comme autónomo, RETA et IRPF sont désormais calculés à partir des transactions réelles que tu enregistres, mois après mois.',
    wn0827_1_t: 'Répartition des dépenses plus fiable',
    wn0827_1_d: 'Qui doit quoi à qui est désormais toujours correct même pour ceux qui rejoignent un groupe plus tard (pas seulement pour son créateur), et deux personnes portant le même nom ne se confondent plus.',
    wn0827_2_t: 'Synchronisation entre appareils, corrigée à la racine',
    wn0827_2_d: 'Renommer un groupe, ajouter une dépense ou écrire dans le chat atteint désormais vraiment tes autres appareils connectés, immédiatement.',
    wn0827_3_t: 'Combien te revient vraiment, mois après mois',
    wn0827_3_d: 'Dans l\'analyse d\'une action, un graphique montre désormais combien de sa performance est vraiment « la sienne » et pas seulement le marché qui monte — mois après mois, pas juste un chiffre unique.',
    wn0828_0_t: 'Tes canaux d\'import, surveillés tout seuls',
    wn0828_0_d: 'Les captures, CSV et PDF qui se montrent fiables commencent à s\'enregistrer tout seuls, sans demander de confirmation à chaque fois — visible dans Momentum Vault, sous les imports.',
    wn0828_1_t: 'La sauvegarde avant de l\'installer comme application',
    wn0828_1_d: 'Sur iPhone, ajouter Momentum à l\'écran d\'accueil avertit désormais d\'enregistrer une sauvegarde avant — et qui l\'a déjà utilisé depuis un navigateur peut récupérer ses données en un geste.',
    wn0828_2_t: 'Plus de doublons entre notification et relevé',
    wn0828_2_d: 'Une dépense vue d\'abord par une notification ou une capture, puis confirmée par le relevé bancaire arrivé après, n\'apparaît plus deux fois.',
    wn0828_3_t: 'L\'appli te dit quand elle a appris quelque chose',
    wn0828_3_d: 'Corriger la catégorie d\'une dépense montre désormais immédiatement que Momentum s\'en souviendra — ce n\'est plus un changement invisible.',
    wn0830_0_t: 'Demande juste "Apple" ou "Tesla"',
    wn0830_0_d: 'Écrire le nom sec d\'une action ou d\'une crypto dans le chat fonctionne maintenant — avant il fallait une phrase complète ("combien vaut..."), et si vraiment rien n\'est trouvé, c\'est maintenant dit clairement, plutôt que le sempiternel "je ne sais pas encore".',
    wn0830_1_t: 'Historique des cours boursiers, sans aucune configuration',
    wn0830_1_d: 'Apple, Tesla, NVIDIA et bien d\'autres affichent maintenant un vrai graphique historique même sans clé de données personnelle — toujours indiqué honnêtement quand le prix vient de cette source.',
    wn0830_2_t: 'Comparables et positionnement crypto, aussi dans le chat',
    wn0830_2_d: 'La comparaison avec les pairs (EV/EBITDA) et le positionnement sur les dérivés crypto (funding rate, surpeuplement) n\'étaient qu\'un bouton — on peut maintenant aussi les demander en écrivant, ex. "suis-je trop exposé sur bitcoin ?".',
    wn0830_3_t: 'Plus jamais d\'attente infinie',
    wn0830_3_d: 'Si une source externe ne répond pas, Momentum le dit maintenant en quelques secondes au lieu de rester bloqué sur "je cherche..." pour toujours.',
