    wnEyebrow: 'Momentum · Novedades',
    wnTitle: 'Novedades',
    wnClose: 'Entendido',
    wn0720_0_t: 'Un solo estilo, en todas partes',
    wn0720_0_d: 'Iconos coherentes en lugar de emojis dispersos, y los términos técnicos traducidos claramente (ej. "Decidido" en vez de "Apex Predator") — el mismo Momentum, más fácil de leer de un vistazo.',
    wn0720_1_t: 'Factura electrónica real, no solo un PDF',
    wn0720_1_d: 'Si tienes Partita IVA italiana, ahora puedes generar el XML oficial FatturaPA directamente en el móvil, con una guía que indica qué falta antes de subirla.',
    wn0720_2_t: 'Cóbrate con un código QR',
    wn0720_2_d: 'Un código QR de transferencia SEPA listo para escanear con la app del banco — nada de copiar el IBAN a mano.',
    wn0721_0_t: 'Reparte gastos, sin cuenta',
    wn0721_0_d: 'Cena, viaje, alquiler: crea un grupo y sabe al instante quién debe qué a quién — todo se queda en tu móvil, ningún servidor de por medio.',
    wn0721_1_t: 'Crea una factura en pocos toques',
    wn0721_1_d: 'Cliente, importe, concepto: Momentum calcula el neto y la retención al instante y genera el documento listo para enviar.',
    wn0810_0_t: 'La primera pantalla, rediseñada',
    wn0810_0_d: 'El número que de verdad importa — cuánto puedes gastar hoy — es ahora lo primero que ves, en el centro, en vez de quedar más abajo.',
    wn0810_1_t: 'Números más fáciles de leer',
    wn0810_1_d: 'Un estilo único para cada tipo de texto en toda la app — de un vistazo se distingue qué es un dato real y qué es solo una explicación.',
    wn0817_0_t: 'Notificaciones, una a una',
    wn0817_0_d: 'Plazos fiscales, cambios de normativa, alertas de precio: ahora cada una se puede apagar por separado — ya no hace falta desactivarlas todas para quitar solo una.',
    wn0817_1_t: 'Entiende el significado, no solo las palabras',
    wn0817_1_d: 'Un modelo de comprensión del lenguaje local (opcional, descargable en Momentum Vault) ahora reconoce una pregunta aunque la formules de otra manera.',
    wn0826_0_t: 'Cuatro preguntas, a tu medida',
    wn0826_0_d: 'El primer inicio ahora también pregunta cuánto podrías aguantar si tus ingresos se detuvieran — y te muestra al instante qué cambió para ti, con tus números reales.',
    wn0826_1_t: '"No invierto" es ahora una respuesta válida',
    wn0826_1_d: 'Quien elige no invertir ya no recibe sugerencias para hacerlo — la app respeta la elección en vez de insistir.',
    wn0827_0_t: 'Autónomo en España, con tus facturas reales',
    wn0827_0_d: 'Ya no es solo un simulador: si trabajas como autónomo, RETA e IRPF ahora se calculan desde las transacciones reales que registras, mes a mes.',
    wn0827_1_t: 'División de gastos más fiable',
    wn0827_1_d: 'Quién debe qué a quién ahora es siempre correcto incluso para quien se une a un grupo más tarde (no solo para quien lo crea), y dos personas con el mismo nombre ya no se confunden.',
    wn0827_2_t: 'Sincronización entre dispositivos, corregida de raíz',
    wn0827_2_d: 'Renombrar un grupo, añadir un gasto o escribir en el chat ahora llega de verdad a tus otros dispositivos conectados, al instante.',
    wn0827_3_t: 'Cuánto es realmente mérito tuyo, mes a mes',
    wn0827_3_d: 'En el análisis de una acción, un gráfico ahora muestra cuánto de su rendimiento es realmente "suyo" y no solo el mercado subiendo — mes a mes, no solo un número único.',
    wn0828_0_t: 'Tus canales de importación, vigilados solos',
    wn0828_0_d: 'Capturas, CSV y PDF que demuestran ser fiables empiezan a guardarse solos, sin pedir confirmación cada vez — visible en Momentum Vault, en importaciones.',
    wn0828_1_t: 'La copia de seguridad antes de instalarla como app',
    wn0828_1_d: 'En iPhone, añadir Momentum a la pantalla de inicio ahora avisa de guardar una copia de seguridad antes — y quien ya la usó desde un navegador puede recuperar sus datos con un toque.',
    wn0828_2_t: 'Ya no hay duplicados entre notificación y extracto',
    wn0828_2_d: 'Un gasto visto primero por una notificación o captura, y luego confirmado por el extracto bancario que llega después, ya no aparece dos veces.',
    wn0828_3_t: 'La app te dice cuándo ha aprendido algo',
    wn0828_3_d: 'Corregir la categoría de un gasto ahora muestra al instante que Momentum lo recordará — ya no es un cambio invisible.',
    wn0830_0_t: 'Pregunta solo "Apple" o "Tesla"',
    wn0830_0_d: 'Escribir el nombre seco de una acción o una cripto en el chat ahora funciona — antes hacía falta una frase completa ("cuánto vale..."), y si de verdad no encuentra nada te lo dice claramente, en vez del típico "no lo sé todavía".',
    wn0830_1_t: 'Histórico de precios de acciones, sin configurar nada',
    wn0830_1_d: 'Apple, Tesla, NVIDIA y muchas otras ahora muestran un gráfico histórico real incluso sin una clave de datos personal — siempre declarado con honestidad cuando el precio viene de esta fuente.',
    wn0830_2_t: 'Comparables y posicionamiento cripto, también en el chat',
    wn0830_2_d: 'La comparación con pares (EV/EBITDA) y el posicionamiento en derivados cripto (funding rate, aglomeración) antes era solo un botón — ahora también se puede preguntar escribiendo, p. ej. "¿estoy demasiado expuesto en bitcoin?".',
    wn0830_3_t: 'Nunca más una espera infinita',
    wn0830_3_d: 'Si una fuente externa no responde, Momentum ahora lo dice en pocos segundos en vez de quedarse bloqueado en "buscando..." para siempre.',
