    wn0720_1_d: 'Heb je een Italiaans btw-nummer, dan kun je nu de officiële FatturaPA-XML rechtstreeks op je telefoon genereren, met een gids die laat zien wat er nog ontbreekt voordat je hem uploadt.',
    wn0720_2_t: 'Laat je betalen met een QR-code',
    wn0720_2_d: 'Een SEPA-overschrijvings-QR-code klaar om te scannen met je bank-app — geen IBAN meer met de hand overtypen.',
    wn0721_0_t: 'Deel uitgaven, zonder account',
    wn0721_0_d: 'Etentje, reis, huur: maak een groep en weet meteen wie wat aan wie verschuldigd is — alles blijft op je telefoon, geen server ertussen.',
    wn0721_1_t: 'Maak een factuur in een paar tikken',
    wn0721_1_d: 'Klant, bedrag, omschrijving: Momentum berekent netto en bronbelasting meteen en maakt een verzendklaar document.',
    wn0810_0_t: 'Het startscherm, opnieuw ontworpen',
    wn0810_0_d: 'Het getal dat er echt toe doet — hoeveel je vandaag kunt uitgeven — is nu het eerste wat je ziet, centraal, in plaats van verstopt onderaan.',
    wn0810_1_t: 'Cijfers die makkelijker te lezen zijn',
    wn0810_1_d: 'Eén consistente stijl voor elk soort tekst in de hele app — in één oogopslag zie je wat een echt getal is en wat slechts uitleg.',
    wn0817_0_t: 'Meldingen, één voor één',
    wn0817_0_d: 'Belastingtermijnen, wetswijzigingen, prijsalerts: elke categorie kan nu apart worden uitgezet — je hoeft niet meer alles uit te schakelen om er één stil te krijgen.',
    wn0817_1_t: 'Begrijpt de betekenis, niet alleen de woorden',
    wn0817_1_d: 'Een lokaal taalbegrip-model (optioneel, te downloaden in Momentum Vault) herkent een vraag nu ook als je hem anders formuleert dan de eerste keer.',
    wn0826_0_t: 'Vier vragen, op jou afgestemd',
    wn0826_0_d: 'De eerste keer opstarten vraagt nu ook hoelang je het zou volhouden als je inkomen zou stoppen — en laat meteen zien wat er voor jou is veranderd, met jouw echte cijfers.',
    wn0826_1_t: '"Ik beleg niet" is nu een geldig antwoord',
    wn0826_1_d: 'Wie ervoor kiest niet te beleggen, krijgt geen suggesties meer daarover — de app respecteert de keuze in plaats van aan te dringen.',
    wn0827_0_t: 'Partita IVA Spanje, met je echte facturen',
    wn0827_0_d: 'Niet langer alleen een simulator: als je als autónomo werkt, worden RETA en IRPF nu berekend op basis van de echte transacties die je maand na maand registreert.',
    wn0827_1_t: 'Betrouwbaarder kosten delen',
    wn0827_1_d: 'Wie wat aan wie verschuldigd is, klopt nu altijd, ook voor wie later bij een groep komt (niet alleen voor wie hem aanmaakt), en twee mensen met dezelfde naam worden niet meer verward.',
    wn0827_2_t: 'Synchronisatie tussen apparaten, aan de basis opgelost',
    wn0827_2_d: 'Een groep hernoemen, een uitgave toevoegen of in de chat schrijven bereikt nu echt je andere verbonden apparaten, meteen.',
    wn0827_3_t: 'Hoeveel echt aan jou te danken is, maand na maand',
    wn0827_3_d: 'Bij de analyse van een aandeel toont een grafiek nu hoeveel van het rendement echt "van jou" is en niet gewoon de stijgende markt — maand na maand, niet slechts één getal.',
    wn0828_0_t: 'Je importkanalen, die zichzelf in de gaten houden',
    wn0828_0_d: 'Screenshots, CSV en PDF die betrouwbaar blijken beginnen zichzelf op te slaan, zonder telkens om bevestiging te vragen — zichtbaar in Momentum Vault, onder imports.',
    wn0828_1_t: 'De back-upmelding vóór installatie als app',
    wn0828_1_d: 'Op iPhone waarschuwt Momentum aan het beginscherm toevoegen nu om eerst een back-up te maken — en wie het al vanuit een browser gebruikte kan zijn gegevens met één tik herstellen.',
    wn0828_2_t: 'Geen dubbele meer tussen melding en afschrift',
    wn0828_2_d: 'Een uitgave die eerst via een melding of screenshot werd gezien, en later bevestigd door het bankafschrift dat daarna binnenkomt, verschijnt niet meer dubbel.',
    wn0828_3_t: 'De app laat weten wanneer ze iets heeft geleerd',
    wn0828_3_d: 'De categorie van een uitgave corrigeren toont nu meteen dat Momentum het zal onthouden — geen onzichtbare verandering meer.',
    wn0830_0_t: 'Vraag gewoon "Apple" of "Tesla"',
    wn0830_0_d: 'Een kale naam van een aandeel of crypto typen in de chat werkt nu — vroeger was een volledige zin nodig ("hoeveel is ... waard"), en als er echt niets gevonden wordt, zegt de app dat nu duidelijk, in plaats van het gebruikelijke "weet ik nog niet".',
    wn0830_1_t: 'Historische aandelenkoersen, zonder iets in te stellen',
    wn0830_1_d: 'Apple, Tesla, NVIDIA en vele andere tonen nu een echte historische grafiek, ook zonder eigen datasleutel — altijd eerlijk vermeld wanneer de prijs van deze bron komt.',
    wn0830_2_t: 'Vergelijkbare bedrijven en crypto-positionering, nu ook in de chat',
    wn0830_2_d: 'De vergelijking met branchegenoten (EV/EBITDA) en de positionering in crypto-derivaten (funding rate, drukte) waren eerst alleen een knop — nu kun je het ook typen, bijv. "zit ik te vol in bitcoin?".',
    wn0830_3_t: 'Nooit meer eindeloos wachten',
    wn0830_3_d: 'Als een externe bron niet reageert, zegt Momentum dat nu binnen enkele seconden, in plaats van voor altijd vast te blijven zitten op "aan het zoeken...".',
